main_section_html:
{{ {
    "title": _("Product"),
    "route": "product"
} }}

{% set item_name = frappe.request.path.split('/')[-1] %}
{% set item = frappe.get_all("Item", 
    filters={"item_name": item_name, "disabled": 0},
    fields=["name", "item_name", "item_group", "image", "description", "brand"]
) %}

{% if item and item[0] %}
    {% set item = item[0] %}
    {% set price = frappe.get_all("Item Price", 
        filters={"item_code": item.name, "selling": 1},
        fields=["price_list_rate"],
        order_by="price_list_rate asc",
        limit=1
    ) %}
    {% set stock_qty = frappe.get_all("Bin", 
        filters={"item_code": item.name},
        fields=["sum(actual_qty) as stock_qty"]
    ) %}

    <div class="product-detail-page" style="max-width: 1200px; margin: 0 auto; padding: 40px 20px;">
        <!-- Back Button -->
        <a href="/products" style="display: inline-flex; align-items: center; gap: 8px; color: var(--text-primary); text-decoration: none; margin-bottom: 30px; padding: 8px 16px; border: 1px solid var(--border-color); border-radius: 6px; transition: all 0.2s;">
            <span>←</span>
            Back to Products
        </a>

        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: start;">
            <!-- Product Image -->
            <div class="product-image-section">
                <img src="{{ item.image or '/assets/frappe/images/default-img.png' }}" 
                     alt="{{ item.item_name }}" 
                     style="width: 100%; height: 400px; object-fit: contain; border-radius: 12px; background: var(--bg-secondary); padding: 20px;">
            </div>

            <!-- Product Details -->
            <div class="product-info-section">
                <h1 style="margin: 0 0 12px 0; font-size: 32px; font-weight: 700; color: var(--text-primary);">
                    {{ item.item_name }}
                </h1>

                <div style="color: var(--text-muted); font-size: 14px; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 24px;">
                    {{ item.item_group }}
                </div>

                <div style="font-size: 28px; font-weight: 700; color: var(--success-color); margin-bottom: 24px;">
                    KES {{ "{:,.0f}".format((price[0].price_list_rate if price and price[0] else 0) or 0) }}
                </div>

                <!-- Stock Status -->
                {% set available_stock = (stock_qty[0].stock_qty if stock_qty and stock_qty[0] else 0) or 0 %}
                {% if available_stock > 0 %}
                    <div style="background: var(--success-color); color: white; padding: 8px 16px; border-radius: 6px; display: inline-flex; align-items: center; gap: 8px; margin-bottom: 30px;">
                        <span>✓</span>
                        <span>In Stock</span>
                    </div>

                    <!-- Add to Cart Section -->
                    <div style="display: flex; gap: 12px; align-items: center; margin-bottom: 30px;">
                        <select id="quantitySelect" style="padding: 12px; border: 1px solid var(--border-color); border-radius: 6px; background: var(--bg-card); color: var(--text-primary); min-width: 80px;">
                            {% for q in range(1,6) %}
                                <option value="{{ q }}">{{ q }}</option>
                            {% endfor %}
                        </select>
                        <button onclick="addToCart()" 
                               style="background: var(--accent-color); color: var(--bg-primary); padding: 12px 24px; border-radius: 6px; text-decoration: none; font-weight: 600; transition: all 0.2s; border: 1px solid var(--accent-color); cursor: pointer;">
                            Add to Cart
                        </button>
                    </div>
                {% else %}
                    <div style="background: var(--danger-color); color: white; padding: 8px 16px; border-radius: 6px; display: inline-flex; align-items: center; gap: 8px; margin-bottom: 30px;">
                        <span>✗</span>
                        <span>Out of Stock</span>
                    </div>
                    <p style="color: var(--text-muted); margin-bottom: 30px;">Please contact us for availability and restocking information.</p>
                {% endif %}

                <!-- Description -->
                {% if item.description %}
                    <div style="border-top: 1px solid var(--border-color); padding-top: 30px;">
                        <h3 style="margin: 0 0 16px 0; color: var(--text-primary);">Product Description</h3>
                        <div style="line-height: 1.6; color: var(--text-secondary); white-space: pre-line;">
                            {{ item.description }}
                        </div>
                    </div>
                {% endif %}

                <!-- Additional Item Details -->
                <div style="border-top: 1px solid var(--border-color); padding-top: 30px;">
                    <h4 style="margin: 0 0 16px 0; color: var(--text-primary);">Product Details</h4>
                    <div style="display: grid; gap: 8px;">
                        <div style="display: flex; justify-content: space-between;">
                            <span style="color: var(--text-muted);">Item Code:</span>
                            <span style="color: var(--text-primary); font-weight: 500;">{{ item.name }}</span>
                        </div>
                        <div style="display: flex; justify-content: space-between;">
                            <span style="color: var(--text-muted);">Item Group:</span>
                            <span style="color: var(--text-primary); font-weight: 500;">{{ item.item_group }}</span>
                        </div>
                        {% if item.brand %}
                        <div style="display: flex; justify-content: space-between;">
                            <span style="color: var(--text-muted);">Brand:</span>
                            <span style="color: var(--text-primary); font-weight: 500;">{{ item.brand }}</span>
                        </div>
                        {% endif %}
                    </div>
                </div>
            </div>
        </div>
    </div>

    <script>
    function addToCart() {
        const quantity = document.getElementById('quantitySelect').value;
        const itemCode = "{{ item.name }}";
        window.location.href = `/cart?item=${encodeURIComponent(itemCode)}&qty=${quantity}`;
    }
    </script>

    <style>
    .product-detail-page {
        font-family: "Inter", "Helvetica Neue", Arial, sans-serif;
    }

    @media (max-width: 768px) {
        .product-detail-page {
            padding: 20px 16px;
        }

        .product-detail-page > div {
            grid-template-columns: 1fr;
            gap: 30px;
        }

        .product-image-section img {
            height: 300px;
        }
    }
    </style>

{% else %}
    <!-- Product Not Found -->
    <div style="text-align: center; padding: 80px 20px;">
        <div style="font-size: 48px; margin-bottom: 20px;">😕</div>
        <h1 style="margin: 0 0 16px 0; color: var(--text-primary);">Product Not Found</h1>
        <p style="color: var(--text-muted); margin-bottom: 30px;">The product "{{ item_name }}" doesn't exist or may have been removed.</p>
        <a href="/products" 
           style="background: var(--accent-color); color: var(--bg-primary); padding: 12px 24px; border-radius: 6px; text-decoration: none; font-weight: 500;">
            Back to Products
        </a>
    </div>
{% endif %}

{% set products = frappe.db.sql("""
    SELECT 
        i.name,
        i.item_name,
        i.item_group,
        i.image,
        (SELECT price_list_rate FROM `tabItem Price` ip 
         WHERE ip.item_code = i.name 
         AND ip.price_list = 'Standard Selling' 
         LIMIT 1) AS price,
        (SELECT SUM(bin.actual_qty) FROM `tabBin` bin WHERE bin.item_code = i.name) AS stock_qty
    FROM `tabItem` i
    WHERE i.is_sales_item = 1 AND i.disabled = 0
    AND i.item_group NOT IN ('Consumable', 'Sub Assemblies', 'Services', 'Raw Material', 'Products', 'All Item Groups')
""", as_dict=True) %}

<style>
:root {
    --bg-primary: #ffffff;
    --bg-secondary: #f8f9fa;
    --bg-card: #ffffff;
    --text-primary: #000000;
    --text-secondary: #6c757d;
    --text-muted: #8d99a6;
    --border-color: #e9ecef;
    --border-hover: #dee2e6;
    --accent-color: #000000;
    --accent-hover: #333333;
    --success-color: #198754;
    --danger-color: #dc3545;
    --shadow: 0 2px 8px rgba(0,0,0,0.08);
    --shadow-hover: 0 4px 16px rgba(0,0,0,0.12);
}

[data-theme="dark"] {
    --bg-primary: #1a1a1a;
    --bg-secondary: #2d2d2d;
    --bg-card: #2d2d2d;
    --text-primary: #ffffff;
    --text-secondary: #adb5bd;
    --text-muted: #6c757d;
    --border-color: #404040;
    --border-hover: #555555;
    --accent-color: #ffffff;
    --accent-hover: #e0e0e0;
    --success-color: #20c997;
    --danger-color: #ff6b6b;
    --shadow: 0 2px 8px rgba(0,0,0,0.3);
    --shadow-hover: 0 4px 16px rgba(0,0,0,0.4);
}

.products-page { 
    display: flex; 
    gap: 24px; 
    padding: 20px; 
    font-family: "Inter", "Helvetica Neue", Arial, sans-serif;
    background: var(--bg-primary);
    color: var(--text-primary);
    min-height: 100vh;
}

.filters { 
    width: 260px; 
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    padding: 20px;
    border-radius: 12px;
    height: fit-content;
    position: sticky;
    top: 20px;
}

.filters h3 { 
    margin: 0 0 16px 0; 
    font-size: 18px;
    font-weight: 600;
}

.filters h5 {
    margin: 0 0 8px 0;
    font-size: 14px;
    font-weight: 600;
    color: var(--text-secondary);
}

.filters label { 
    display: block; 
    margin-bottom: 8px; 
    font-size: 14px; 
    cursor: pointer;
    color: var(--text-secondary);
    transition: color 0.2s;
}

.filters label:hover {
    color: var(--text-primary);
}

.product-area { 
    flex: 1; 
    min-width: 0;
}

.top-bar { 
    display: flex; 
    justify-content: space-between; 
    align-items: flex-start;
    margin-bottom: 20px; 
    gap: 16px;
}

.top-bar h2 {
    margin: 0; 
    font-size: 24px;
    font-weight: 700;
}

.search-box { 
    width: 100%; 
    max-width: 400px; 
    padding: 12px 16px; 
    border-radius: 8px; 
    border: 1px solid var(--border-color);
    background: var(--bg-card);
    color: var(--text-primary);
    font-size: 14px;
    transition: all 0.2s;
}

.search-box:focus {
    outline: none;
    border-color: var(--accent-color);
    box-shadow: 0 0 0 2px rgba(0,0,0,0.1);
}

.product-grid { 
    display: grid; 
    grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); 
    gap: 20px; 
    margin-bottom: 32px;
}

.product-card { 
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    border-radius: 12px;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    transition: all 0.3s ease;
    height: fit-content;
}

.product-card:hover {
    border-color: var(--border-hover);
    box-shadow: var(--shadow-hover);
    transform: translateY(-2px);
}

.product-image {
    height: 160px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--bg-secondary);
    overflow: hidden;
    flex-shrink: 0;
}

.product-image img {
    max-width: 100%;
    max-height: 100%;
    object-fit: contain;
    transition: transform 0.3s ease;
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.product-body {
    padding: 16px;
    display: flex;
    flex-direction: column;
    gap: 8px;
    flex: 1;
    min-height: 0;
}

.product-name-link {
    text-decoration: none;
    color: inherit;
    display: block;
}

.product-name {
    font-weight: 600;
    font-size: 16px;
    line-height: 1.3;
    margin: 0;
    color: var(--text-primary);
    transition: color 0.2s ease;
    position: relative;
    display: inline-block;
}

.product-name:hover {
    color: var(--success-color);
}

.product-name::after {
    content: '';
    position: absolute;
    width: 0;
    height: 1px;
    bottom: -2px;
    left: 0;
    background-color: var(--success-color);
    transition: width 0.2s ease;
}

.product-name:hover::after {
    width: 100%;
}

.product-group {
    font-size: 13px;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    font-weight: 500;
    margin: 0;
}

.product-meta {
    display: flex;
    flex-direction: column;
    gap: 12px;
    margin-top: auto;
}

.price-section {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.product-price {
    font-weight: 700;
    font-size: 16px;
    color: var(--success-color);
    margin: 0;
}

.stock-status {
    font-size: 12px;
    font-weight: 500;
    padding: 4px 8px;
    border-radius: 4px;
    background: var(--success-color);
    color: white;
}

.stock-status.out-of-stock {
    background: var(--danger-color);
}

.card-actions {
    display: flex;
    gap: 8px;
    align-items: center;
    justify-content: space-between;
}

.add-cart-btn {
    padding: 10px 16px;
    border-radius: 6px;
    text-decoration: none;
    font-size: 14px;
    cursor: pointer;
    border: 1px solid transparent;
    font-weight: 500;
    transition: all 0.2s;
    white-space: nowrap;
    background: var(--accent-color);
    color: white;
    border-color: var(--accent-color);
    width: 100%;
    text-align: center;
}

.add-cart-btn:hover {
    background: var(--accent-hover);
    border-color: var(--accent-hover);
    transform: translateY(-1px);
    text-decoration: none;
    color: white;
}

.out-of-stock-section {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.product-oos {
    color: var(--danger-color);
    font-weight: 700;
    font-size: 14px;
    margin: 0;
}

.contact-link {
    color: var(--text-muted);
    text-decoration: none;
    font-size: 12px;
    transition: color 0.2s ease;
}

.contact-link:hover {
    color: var(--accent-color);
    text-decoration: underline;
}

/* Clean Pagination */
.pagination {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 12px;
    margin-top: 40px;
    padding: 20px 0;
}

.pagination-btn {
    padding: 10px 16px;
    border: 1px solid var(--border-color);
    background: var(--bg-card);
    color: var(--text-primary);
    border-radius: 8px;
    cursor: pointer;
    font-size: 14px;
    font-weight: 500;
    transition: all 0.2s;
    min-width: 100px;
}

.pagination-btn:hover:not(:disabled) {
    background: var(--accent-color);
    color: var(--bg-primary);
    border-color: var(--accent-color);
}

.pagination-btn:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

.pagination-pages {
    display: flex;
    gap: 4px;
    align-items: center;
}

.pagination-page {
    padding: 8px 12px;
    border-radius: 6px;
    font-size: 14px;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
    min-width: 40px;
    text-align: center;
}

.pagination-page.active {
    background: var(--accent-color);
    color: var(--bg-primary);
}

.pagination-page:not(.active) {
    background: transparent;
    color: var(--text-secondary);
}

.pagination-page:not(.active):hover {
    background: var(--bg-secondary);
    color: var(--text-primary);
}

.pagination-info {
    font-size: 14px;
    color: var(--text-muted);
    font-weight: 500;
}

.small-muted { 
    font-size: 12px; 
    color: var(--text-muted);
    margin: 0;
}

.no-results { 
    padding: 40px; 
    text-align: center; 
    color: var(--text-muted);
    font-size: 16px;
    grid-column: 1 / -1;
}

@media (max-width: 768px) {
    .products-page {
        flex-direction: column;
        padding: 16px;
        gap: 16px;
    }

    .filters {
        width: 100%;
        position: static;
    }

    .top-bar {
        flex-direction: column;
        align-items: stretch;
    }

    .search-box {
        max-width: none;
    }

    .product-grid {
        grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
        gap: 12px;
    }

    .product-image {
        height: 140px;
    }

    .card-actions {
        flex-direction: column;
        gap: 8px;
    }

    .add-cart-btn {
        min-width: auto;
        flex: 1;
        text-align: center;
    }

    .pagination {
        flex-wrap: wrap;
        gap: 8px;
    }

    .pagination-info {
        order: -1;
        width: 100%;
        text-align: center;
        margin-bottom: 12px;
    }
}
</style>

<div class="products-page">
    <div class="filters">
        <h3>Filters</h3>
        <h5>Item Group</h5>
        {% set item_groups = frappe.get_all("Item Group", 
            filters={"name": ["not in", ["Consumable", "Sub Assemblies", "Services", "Raw Material", "Products", "All Item Groups"]]},
            fields=["name"]) %}
        <div id="group-filters">
            {% for g in item_groups %}
                <label>
                    <input type="checkbox" class="group-checkbox" value="{{ g.name|e }}"> {{ g.name }}
                </label>
            {% endfor %}
        </div>
    </div>

    <div class="product-area">
        <div class="top-bar">
            <div>
                <h2>All Products</h2>
                <div class="small-muted" id="productCount">Showing {{ products|length }} items</div>
            </div>
            <input id="searchBox" type="text" placeholder="Search for Products" class="search-box">
        </div>

        <div id="productGrid" class="product-grid">
            {% for p in products %}
                <div class="product-card" data-name="{{ (p.item_name or p.name)|lower }}" data-group="{{ (p.item_group or '')|lower }}" data-instock="{{ (p.stock_qty or 0) > 0 }}">
                    <div class="product-image">
                        <img src="{{ (p.image or '/assets/frappe/images/default-img.png')|e }}" alt="{{ p.item_name|e }}" loading="lazy">
                    </div>

                    <div class="product-body">
                        <a href="/product/{{ p.name }}" class="product-name-link">
                            <div class="product-name">{{ p.item_name }}</div>
                        </a>
                        <div class="product-group">{{ p.item_group }}</div>

                        <div class="product-meta">
                            {% if p.stock_qty and p.stock_qty|int > 0 %}
                                <div class="price-section">
                                    <div class="product-price">KES {{ "{:,.0f}".format(p.price or 0) }}</div>
                                    <div class="stock-status">In stock</div>
                                </div>
                                <div class="card-actions">
                                    <a href="/cart?item={{ p.name }}&qty=1" class="add-cart-btn">Add to Cart</a>
                                </div>
                            {% else %}
                                <!-- UPDATED: Only show one "Out of stock" message with contact link -->
                                <div class="out-of-stock-section">
                                    <div class="product-price">KES {{ "{:,.0f}".format(p.price or 0) }}</div>
                                    <div class="product-oos">Out of stock</div>
                                    <a href="/contact" class="contact-link">Contact us for availability</a>
                                </div>
                            {% endif %}
                        </div>
                    </div>
                </div>
            {% endfor %}
        </div>

        <div id="pagination" class="pagination" style="display: none;">
            <button class="pagination-btn" id="prevPage" disabled>Previous</button>
            <div id="paginationPages" class="pagination-pages"></div>
            <div class="pagination-info" id="pageInfo"></div>
            <button class="pagination-btn" id="nextPage">Next</button>
        </div>

        <div id="noResults" class="no-results" style="display:none;">No products match your search or filters.</div>
    </div>
</div>

<script>
(function () {
    const searchBox = document.getElementById('searchBox');
    const groupCheckboxes = Array.from(document.querySelectorAll('.group-checkbox'));
    const productGrid = document.getElementById('productGrid');
    const productCards = Array.from(productGrid.querySelectorAll('.product-card'));
    const noResults = document.getElementById('noResults');
    const productCount = document.getElementById('productCount');
    const pagination = document.getElementById('pagination');
    const prevPageBtn = document.getElementById('prevPage');
    const nextPageBtn = document.getElementById('nextPage');
    const paginationPages = document.getElementById('paginationPages');
    const pageInfo = document.getElementById('pageInfo');

    const itemsPerPage = 12;
    let currentPage = 1;
    let filteredProducts = [];

    function normalize(s) { return (s || '').toString().toLowerCase().trim(); }

    function filterProducts() {
        const q = normalize(searchBox.value);
        const activeGroups = groupCheckboxes.filter(cb => cb.checked).map(cb => normalize(cb.value));

        filteredProducts = productCards.filter(card => {
            const name = card.getAttribute('data-name') || '';
            const group = card.getAttribute('data-group') || '';
            const matchesQuery = q === '' || name.includes(q) || group.includes(q);
            const matchesGroup = activeGroups.length === 0 || activeGroups.includes(group);
            return matchesQuery && matchesGroup;
        });

        updateProductCount();
        currentPage = 1;
        renderPagination();
        renderProducts();
    }

    function updateProductCount() {
        const count = filteredProducts.length;
        productCount.textContent = `Showing ${count} item${count !== 1 ? 's' : ''}`;
        noResults.style.display = count === 0 ? 'block' : 'none';
        pagination.style.display = count > itemsPerPage ? 'flex' : 'none';
    }

    function renderProducts() {
        productCards.forEach(card => card.style.display = 'none');

        const startIndex = (currentPage - 1) * itemsPerPage;
        const endIndex = startIndex + itemsPerPage;
        const productsToShow = filteredProducts.slice(startIndex, endIndex);

        productsToShow.forEach(card => card.style.display = '');
        updatePaginationInfo();
    }

    function renderPagination() {
        const totalPages = Math.ceil(filteredProducts.length / itemsPerPage);
        paginationPages.innerHTML = '';

        // Show smart page numbers
        const pagesToShow = new Set();
        pagesToShow.add(1);
        pagesToShow.add(totalPages);

        for (let i = Math.max(1, currentPage - 1); i <= Math.min(totalPages, currentPage + 1); i++) {
            pagesToShow.add(i);
        }

        Array.from(pagesToShow)
            .sort((a, b) => a - b)
            .forEach((page, index, array) => {
                if (index > 0 && page - array[index - 1] > 1) {
                    const ellipsis = document.createElement('span');
                    ellipsis.textContent = '...';
                    ellipsis.style.color = 'var(--text-muted)';
                    ellipsis.style.padding = '0 8px';
                    paginationPages.appendChild(ellipsis);
                }

                const pageBtn = document.createElement('div');
                pageBtn.className = `pagination-page ${page === currentPage ? 'active' : ''}`;
                pageBtn.textContent = page;
                pageBtn.addEventListener('click', () => {
                    currentPage = page;
                    renderPagination();
                    renderProducts();
                });
                paginationPages.appendChild(pageBtn);
            });

        prevPageBtn.disabled = currentPage === 1;
        nextPageBtn.disabled = currentPage === totalPages;
    }

    function updatePaginationInfo() {
        const startItem = (currentPage - 1) * itemsPerPage + 1;
        const endItem = Math.min(currentPage * itemsPerPage, filteredProducts.length);
        pageInfo.textContent = `${startItem}-${endItem} of ${filteredProducts.length}`;
    }

    // Event Listeners
    searchBox.addEventListener('input', filterProducts);
    groupCheckboxes.forEach(cb => cb.addEventListener('change', filterProducts));

    prevPageBtn.addEventListener('click', () => {
        if (currentPage > 1) {
            currentPage--;
            renderPagination();
            renderProducts();
        }
    });

    nextPageBtn.addEventListener('click', () => {
        const totalPages = Math.ceil(filteredProducts.length / itemsPerPage);
        if (currentPage < totalPages) {
            currentPage++;
            renderPagination();
            renderProducts();
        }
    });

    // Initialize
    filteredProducts = productCards;
    updateProductCount();
    renderPagination();
    renderProducts();

    // Auto-detect Frappe dark mode
    function detectFrappeTheme() {
        const html = document.documentElement;
        if (document.body.classList.contains('dark-mode')) {
            html.setAttribute('data-theme', 'dark');
        } else {
            html.removeAttribute('data-theme');
        }
    }

    const observer = new MutationObserver(detectFrappeTheme);
    observer.observe(document.body, { attributes: true, attributeFilter: ['class'] });
    detectFrappeTheme();
})();
</script>
